        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    ];

    // Full 256-byte lookup for scalar fallback
    private static readonly byte[] ScalarLut = CreateScalarLut();

    private static byte[] CreateScalarLut()
    {
        var lut = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            lut[i] = (byte)(((i * 0x0202020202UL) & 0x010884422010UL) % 1023);
        }
        return lut;
    }

    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static void ReverseInPlace(Span<byte> data)
    {
        if (Avx2.IsSupported)
        {
            ReverseAvx2(data);
        }
        else if (Ssse3.IsSupported)
        {
            ReverseSsse3(data);
        }
        else if (AdvSimd.IsSupported)
        {
            ReverseNeon(data);
        }
        else
        {
            ReverseScalar(data);
        }
    }

